def roll_event_drop_rules(mob, rules, random_func=None):
    """Pure additive event-drop roll; returns award payloads without DB mutation."""
    import random
    import events as seasonal_events
    roller=random_func or random.random
    validated=seasonal_events.validate_event_drop_rules(rules,mob)
    awards=[]
    for rule in validated:
        roll=float(roller())
        if roll < float(rule["chance_percent"]) / 100.0:
            awards.append({"rule_id":rule["rule_id"],"event_key":rule["event_key"],"item_id":rule["item_id"],"quantity":rule["quantity"]})
    return tuple(awards)

